CREATE OR REPLACE MATERIALIZED VIEW "SQLDBM_DEMO".HEATHER_GOLD.MV_HIGH_VALUE_CUSTOMERS
(
  CUSTOMER_HASH_KEY,
  CUSTKEY,
  NAME,
